            v, build = v.split('+', 1)
            build_ids = build.split('.')
        else:
            build_ids = None
        if v[:1] in ('v', 'V'):
            v = v[1:]
        if '-' in v:
            core, pre = v.split('-', 1)
            pre_ids = pre.split('.')
        else:
            core, pre_ids = v, None
        return [int(x) for x in core.split('.')], pre_ids, build_ids

    def id_key(s):
        if is_num(s):
            return (0, int(s), '', 0)
        i = len(s)
        while i > 0 and s[i - 1] in '0123456789':
            i -= 1
        prefix, digits = s[:i], s[i:]
        return (1, 0, prefix, int(digits) if digits else -1)

