            return 1 if pre_a is None else -1
    else:
        c = cmp_ids(pre_a, pre_b)
        if c:
            return c
    if build_a is None or build_b is None:
        if build_a is None and build_b is None:
            return 0
        return -1 if build_a is None else 1
    return cmp_ids(build_a, build_b)

