def wrap_text(text: str, width: int) -> list:
    paragraphs = []
    current = []
    for raw in text.split('\n'):
        if raw.strip() == '':
            if current:
                paragraphs.append(current)
                current = []
        else:
            current.extend(raw.split())
    if current:
        paragraphs.append(current)

    def sep_after(word):
        return '  ' if word[-1] in '.!?' else ' '

    out = []
    for p_index, words in enumerate(paragraphs):
        if p_index:
            out.append('')
        line = ''
        last = ''
        for word in words:
            if len(word) <= width:
                if not line:
                    line = word
                elif len(line) + len(sep_after(last)) + len(word) <= width:
                    line += sep_after(last) + word
                else:
                    out.append(line)
                    line = word
                last = word
                continue
            rest = word
            if line:
                sep = sep_after(last)
                room = width - len(line) - len(sep)
                if room >= 2:
                    out.append(line + sep + word[:room])
                    rest = word[room:]
                else:
                    out.append(line)
                line = ''
            while len(rest) > width:
                out.append(rest[:width])
                rest = rest[width:]
            line = rest
            last = rest
        if line:
            out.append(line)
    return out

