import pytest


def test_pairs_and_bare_keys():
    assert parse_logfmt("level=info msg=started debug") == {"level": "info", "msg": "started", "debug": True}
    assert parse_logfmt("   a=x    b=y   ") == {"a": "x", "b": "y"}
    assert parse_logfmt("") == {}
    assert parse_logfmt("    ") == {}
    assert parse_logfmt("k= z") == {"k": "", "z": True}
    assert parse_logfmt("svc.name=api-gw http-code=OK") == {"svc.name": "api-gw", "http-code": "OK"}


def test_quoted_values_and_escapes():
    assert parse_logfmt(r'msg="hello world" path="C:\\tmp"') == {"msg": "hello world", "path": "C:\\tmp"}
    assert parse_logfmt(r'q="say \"hi\"" e="" nl="a\nb"') == {"q": 'say "hi"', "e": "", "nl": "a\nb"}
    assert parse_logfmt(r'x="a=b c"') == {"x": "a=b c"}


def test_errors():
    for bad in ['a="x"b', 'a=b"c', 'a="abc', r'a="\t"', '=v', 'a==b', 'k@=1', 'a=1"', '"a"=1', 'a="x\\']:
        with pytest.raises(ValueError):
            parse_logfmt(bad)


def test_conversions():
    got = parse_logfmt('a=42 b=-7 c=007 d=true e=false f=True g="5" h="true" i=- j=4.5 k=+3 l=')
    assert got == {"a": 42, "b": -7, "c": 7, "d": True, "e": False, "f": "True", "g": "5",
                   "h": "true", "i": "-", "j": 4.5, "k": "+3", "l": ""}
    assert type(got["a"]) is int and type(got["d"]) is bool and type(got["g"]) is str
    assert type(got["j"]) is float


def test_float_conversion_edges():
    got = parse_logfmt('m=-0.25 n=1. o=.5 p=1.2.3 q=1e5 r="2.5" s=-.5 t=10.0')
    assert got == {"m": -0.25, "n": "1.", "o": ".5", "p": "1.2.3", "q": "1e5", "r": "2.5", "s": "-.5", "t": 10.0}
    assert type(got["t"]) is float and type(got["r"]) is str


def test_duplicate_keys_collect_lists():
    assert parse_logfmt("tag=a tag=b x=1 tag=3") == {"tag": ["a", "b", 3], "x": 1}
    got = parse_logfmt('f f=0 f="0" f=false')
    assert got == {"f": [True, 0, "0", False]}
    assert [type(v) for v in got["f"]] == [bool, int, str, bool]
    assert parse_logfmt("a=1 b=2") == {"a": 1, "b": 2}


def test_duplicate_keys_are_case_insensitive():
    assert parse_logfmt("Level=info level=warn LEVEL") == {"Level": ["info", "warn", True]}
    assert parse_logfmt("a=1 A=2.5 b=3") == {"a": [1, 2.5], "b": 3}
    assert parse_logfmt("Foo=1 bar=x") == {"Foo": 1, "bar": "x"}

