import pytest


def test_sections_keys_and_comments():
    text = ("top = 1\n# comment\n   ; indented comment\n\n[Server]\nHost = example.com \n"
            "port=8080\n[ Paths ]\nroot = /var/www = x\n")
    assert parse_config(text) == {
        "": {"top": "1"},
        "Server": {"host": "example.com", "port": "8080"},
        "Paths": {"root": "/var/www = x"},
    }


def test_default_section_and_repeats():
    assert parse_config("[a]\n[b]\nx=1\n") == {"a": {}, "b": {"x": "1"}}
    assert parse_config("") == {}
    assert parse_config("# only a comment\n") == {}
    text = "[A]\nk = 1\n[a]\nk = 2\n[A]\nK = 3\nj =\n"
    assert parse_config(text) == {"A": {"k": "3", "j": ""}, "a": {"k": "2"}}


def test_errors():
    for bad in ["just text", "= value", "[a]\n  = 1", "[a]b", "[s]\n   orphan line\n"]:
        with pytest.raises(ValueError):
            parse_config(bad)


def test_continuation_lines():
    text = "[s]\nmsg = hello\n   big\n\tworld\nnext = 2\n"
    assert parse_config(text) == {"s": {"msg": "hello big world", "next": "2"}}


def test_continuation_takes_precedence_over_key_and_header_syntax():
    assert parse_config("a = 1\n  b = 2\n  [x]\n") == {"": {"a": "1 b = 2 [x]"}}


def test_comment_or_blank_line_ends_continuation():
    text = "a = 1\n  # note\n  b = 2\n\n  c = 3\n"
    assert parse_config(text) == {"": {"a": "1", "b": "2", "c": "3"}}
    assert parse_config("a = 1\n# note\n  b = 2\n;x\n\tc = 3\n") == {"": {"a": "1", "b": "2", "c": "3"}}


def test_references():
    text = ("[paths]\nroot = /srv\nlogs = ${root}/logs\n"
            "[app]\nlog = ${paths:LOGS}/app.log\nname = A$$B\n")
    assert parse_config(text) == {
        "paths": {"root": "/srv", "logs": "/srv/logs"},
        "app": {"log": "/srv/logs/app.log", "name": "A$B"},
    }


def test_references_use_final_values_and_are_not_rescanned():
    text = "[s]\na = ${b}!\nb = 1\nb = 2\nc = $${b}\nd = ${c}\n"
    assert parse_config(text) == {"s": {"a": "2!", "b": "2", "c": "${b}", "d": "${b}"}}


def test_reference_errors():
    for bad in ["[s]\na = ${nope}", "[s]\na = ${t:a}", "[s]\na = ${b}\nb = ${a}", "[s]\na = x${a}"]:
        with pytest.raises(ValueError):
            parse_config(bad)


def test_inline_comments():
    text = "a = 1 # c\nb = x;y\nurl = http://h/#frag\nk = #\n[s] ; sec\nz = 2\t;tab\nw = p # q = 3\n"
    assert parse_config(text) == {"": {"a": "1", "b": "x;y", "url": "http://h/#frag", "k": ""},
                                  "s": {"z": "2", "w": "p"}}


def test_inline_comment_on_continuation_line():
    assert parse_config("a = 1\n  more # note\n  end;x\n") == {"": {"a": "1 more end;x"}}

