def render_table(header: list, rows: list, max_width: int = 0) -> str:
    ncols = len(header)

    def fmt(v):
        s = f'{v:.2f}' if isinstance(v, float) else str(v)
        if max_width > 0 and len(s) > max_width:
            s = s[:max_width - 1] + '…'
        return s

    def is_num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    for row in rows:
        if len(row) > ncols:
            raise ValueError('row has more cells than the header')
    right = []
    for c in range(ncols):
        body = [row[c] for row in rows if c < len(row)]
        right.append(bool(body) and all(is_num(v) for v in body))

    grid = [[fmt(v) for v in header]]
    for row in rows:
        grid.append([fmt(v) for v in row] + [''] * (ncols - len(row)))
    widths = [max(len(r[c]) for r in grid) for c in range(ncols)]

    def render_line(cells):
        parts = []
        for c, text in enumerate(cells):
            parts.append(text.rjust(widths[c]) if right[c] else text.ljust(widths[c]))
        return ' | '.join(parts).rstrip(' ')

    lines = [render_line(grid[0]), '-+-'.join('-' * w for w in widths)]
    lines.extend(render_line(r) for r in grid[1:])
    return '\n'.join(lines)

