        if e in _SIMPLE:
            out.append(_SIMPLE[e])
            i += 2
        elif e == 'x':
            h = body[i + 2:i + 4]
            if len(h) != 2 or any(ch not in _HEX for ch in h):
                raise ValueError('bad \\x escape')
            out.append(chr(int(h, 16)))
            i += 4
        elif e == 'u':
            cp, i = _read_u(body, i)
            if 0xD800 <= cp <= 0xDFFF:
                raise ValueError('unpaired surrogate')
            out.append(chr(cp))
        elif e == '\n' or (e == '\r' and body[i + 2:i + 3] == '\n'):
            i += 2 if e == '\n' else 3
            while i < n and body[i] in ' \t':
                i += 1
        elif e in _OCT:
            j = i + 1
            while j < n and j < i + 4 and body[j] in _OCT:
                j += 1
            value = int(body[i + 1:j], 8)
            if value > 0o377:
                raise ValueError('octal escape out of range')
            out.append(chr(value))
            i = j
        else:
            raise ValueError('unknown escape \\%s' % e)
    return ''.join(out)
_HEX = '0123456789abcdefABCDEF'
_OCT = '01234567'
_SIMPLE = {'n': '\n', 't': '\t', '\\': '\\', '"': '"', "'": "'"}


def _read_u(body, i):
    """body[i:i+2] is a backslash-u escape start; return (code point, index after it)."""
    if body[i + 2:i + 3] != '{':
        raise ValueError('\\u must be followed by {')
    j = body.find('}', i + 3)
    if j == -1:
        raise ValueError('unclosed \\u{')
    h = body[i + 3:j]
    if not 1 <= len(h) <= 6 or any(ch not in _HEX for ch in h):
        raise ValueError('bad \\u{...} escape')
    cp = int(h, 16)
    if cp > 0x10FFFF:
        raise ValueError('code point too large')
    return cp, j + 1


def decode_literal(body: str) -> str:
    out = []
    i, n = 0, len(body)
    while i < n:
        c = body[i]
        if c != '\\':
            out.append(c)
            i += 1
            continue
        if i + 1 >= n:
            raise ValueError('trailing backslash')
        e = body[i + 1]
        if e in _SIMPLE:
            out.append(_SIMPLE[e])
            i += 2
        elif e == 'x':
            h = body[i + 2:i + 4]
            if len(h) != 2 or any(ch not in _HEX for ch in h):
                raise ValueError('bad \\x escape')
            out.append(chr(int(h, 16)))
            i += 4
        elif e == 'u':
            cp, i = _read_u(body, i)
            if 0xD800 <= cp <= 0xDBFF and body.startswith('\\u', i):
                low, after = _read_u(body, i)
                if 0xDC00 <= low <= 0xDFFF:
                    cp = (cp - 0xD800) * 0x400 + (low - 0xDC00)
                    i = after
            if 0xD800 <= cp <= 0xDFFF:
                raise ValueError('unpaired surrogate')
            out.append(chr(cp))
        elif e == '\n' or (e == '\r' and body[i + 2:i + 3] == '\n'):
            i += 2 if e == '\n' else 3
            while i < n and body[i] in ' \t':
                i += 1
        elif e in _OCT:
            j = i + 1
            while j < n and j < i + 4 and body[j] in _OCT:
                j += 1
            value = int(body[i + 1:j], 8)
            if value > 0o377:
                raise ValueError('octal escape out of range')
            out.append(chr(value))
            i = j
        else:
            raise ValueError('unknown escape \\%s' % e)
    return ''.join(out)
